<script setup lang="ts">
import { computed, nextTick, onUnmounted, reactive, ref, watch } from 'vue'
import { ElMessage } from 'element-plus'
import DeploymentRequirements from './DeploymentRequirements.vue'
import { preflightController, checkStatusLabel, type PreflightStatus } from './preflight'
import { useRouter } from 'vue-router'
import { api } from './api'
import PendingDeployment from './PendingDeployment.vue'
import { scopeLabel } from './monitoring'
import { privateKeyFileReader, maxPrivateKeyBytes } from './privateKeyFile'
import { errorMessage, requestKey, type Settings, type Preview, type Job, type UpgradePreview } from './monitoring'
const props = defineProps<{ modelValue: boolean; nodeId: string }>(), emit = defineEmits<{ 'update:modelValue': [boolean]; saved: [message?:string] }>()
const router = useRouter(), settings = ref<Settings>(), error = ref(''), busy = ref(false), preview = ref<Preview>()
const form = reactive({ id: '', name: '', host: '', enabled: true, mode: 'native', port: 22, auth: 'key', key: '', keySource: 'path', keyContent: '', keyConfigured: false, password: '', override: false, roots: '', extensions: '', excludes: '' })
const connection=ref<PreflightStatus['report']>(),checking=ref(false),operation=ref(''),details=ref<HTMLElement>(),fieldErrors=reactive<Record<string,string>>({})
const pendingAction=ref<'deploy'|'upgrade'>(),checkToken=ref('')
let controller:ReturnType<typeof preflightController>|undefined,submissionKey=requestKey()
const statusText=computed(()=>error.value||operation.value)
const statusType=computed(()=>error.value?'error':pendingAction.value?'warning':busy.value||checking.value?'info':'success')
function showDetails(){details.value?.scrollIntoView({block:'start',behavior:'smooth'})}
async function showError(e:unknown,current:number){if(current!==dialogVersion||!props.modelValue)return;error.value=errorMessage(e);operation.value='';busy.value=false;checking.value=false;const fields:[string,string][]=[['ssh.port','port'],['.host','host'],['.name','name'],['.id','id']];for(const [path,field] of fields)if(error.value.includes(path))fieldErrors[field]=error.value;await nextTick();const first=document.querySelector<HTMLElement>('.node-editor-dialog .el-form-item.is-error input');first?.focus();first?.scrollIntoView?.({block:'center',behavior:'smooth'})}
async function automaticCheck(upgrading=false,active=true){
 controller?.cancel();controller=preflightController();checking.value=true;operation.value=active?'正在检查部署环境与双向连接…':'正在进行只读连接与环境检查…';connection.value=undefined;checkToken.value=''
 const current=dialogVersion,draft=draftVersion
 const input=upgrading?{revision:upgrade.value?.revision,patch:{},node_id:props.nodeId,kind:'upgrade-node',preview_token:upgrade.value?.preview_token}:edit()
 try{const result=await controller.run({...input,active},value=>{if(current!==dialogVersion||draft!==draftVersion||!props.modelValue)return;connection.value=value.report;const last=value.report.items.at(-1);operation.value=value.status==='running'?`正在检查${last?'：'+last.name:' SSH 连接'}…`:'环境检查完成'})
 if(!result||current!==dialogVersion||draft!==draftVersion||!props.modelValue)return
 if(!result.report.ok){operation.value='';error.value='部署前检查未通过，请查看详情并修复后重试。';return}
 checkToken.value=result.id;operation.value=active?'部署前检查通过':'只读检查完成；网络将在部署前主动检测';return result
 }finally{if(current===dialogVersion)checking.value=false}
}
async function checkConnection(){if(checking.value||busy.value)return;error.value='';const current=dialogVersion;try{validateContent();await automaticCheck(false,false)}catch(e){await showError(e,current)}}
const publicMonitor=computed(()=>((settings.value?.values.node_defaults||{}) as Record<string,unknown>).monitor as Record<string,unknown>||{})
let customDraft=false
function overrideChanged(value:unknown){if(value && !customDraft){copyRoots();customDraft=true}}
const upgrade = ref<UpgradePreview>(), upgradeDraft=ref(false)
const deployed=computed(()=>settings.value?.node_deployments?.[props.nodeId])
const savedNode=computed(()=>settings.value?.effective_nodes.find(n=>n.id===props.nodeId))
const canUpgrade=computed(()=>!!props.nodeId&&savedNode.value?.enabled!==false&&['complete','go-rolled-back'].includes(deployed.value?.phase||'')&&!!deployed.value?.version)
async function previewUpgrade(){if(busy.value||checking.value)return;busy.value=true;error.value='';operation.value='正在解析目标版本、下载并校验镜像，请稍候…';const current=dialogVersion;try{const result=await api<UpgradePreview>(`/api/servers/${encodeURIComponent(props.nodeId)}/upgrade-preview`,'POST',{revision:settings.value?.revision});if(current===dialogVersion&&props.modelValue){upgrade.value=result;upgradeDraft.value=!!preview.value||draftVersion>loadedDraftVersion;operation.value=result.no_change?'已是相同版本，无需升级':`升级预览已就绪：${result.current_version||'未知'} → ${result.target_version}，本次不保存草稿`}}catch(e){await showError(e,current)}finally{if(current===dialogVersion)busy.value=false}}
async function submitDeployment(upgrading:boolean,acknowledged=false){
 const current=dialogVersion;operation.value='正在创建部署任务…'
 const input=upgrading?{revision:upgrade.value?.revision,kind:'upgrade-node',node:props.nodeId,preview_token:upgrade.value?.preview_token}:{revision:settings.value?.revision,kind:'add-node',node:form.id.trim(),edit:edit()}
 const job=await api<Job>('/api/deployments','POST',{...input,request_key:submissionKey,preflight_token:checkToken.value,acknowledge_warnings:acknowledged})
 if(current!==dialogVersion||!props.modelValue)return
 emit('update:modelValue',false);emit('saved','任务已创建，正在检查部署环境。');ElMessage.success('任务已创建，正在检查部署环境');await router.push(`/deployments/${job.id}`)
}
async function runUpgrade(){if(busy.value||checking.value||!upgrade.value?.preview_token)return;busy.value=true;error.value='';pendingAction.value=undefined;const current=dialogVersion;try{const result=await automaticCheck(true);if(!result)return;if(result.report.items.some(i=>i.status==='warning')){pendingAction.value='upgrade';operation.value='检查存在警告，请查看详情并确认后继续。';return}await submitDeployment(true)}catch(e){await showError(e,current)}finally{if(current===dialogVersion)busy.value=false}}
async function confirmWarnings(){if(busy.value||!pendingAction.value)return;const upgrading=pendingAction.value==='upgrade';busy.value=true;error.value='';const current=dialogVersion;try{await submitDeployment(upgrading,true);pendingAction.value=undefined}catch(e){await showError(e,current)}finally{if(current===dialogVersion)busy.value=false}}
let loadedDraftVersion=0
const reading=ref(false), fileInput=ref<HTMLInputElement>()
let dialogVersion=0, draftVersion=0
watch(form,()=>{draftVersion++;preview.value=undefined;connection.value=undefined;checkToken.value='';pendingAction.value=undefined;submissionKey=requestKey()},{deep:true,flush:'sync'})
const keyReader=privateKeyFileReader(value=>{form.keyContent=value;preview.value=undefined;error.value=''},message=>{error.value=message},value=>{reading.value=value})
function filesSelected(event:Event){const input=event.target as HTMLInputElement;const files=Array.from(input.files||[]);input.value='';if(files.length&&!busy.value&&!checking.value)void keyReader.read(files)}
function dropped(event:DragEvent){if(!busy.value&&!checking.value)void keyReader.read(Array.from(event.dataTransfer?.files||[]))}
function keySourceChanged(){keyReader.cancel();form.keyContent='';preview.value=undefined;error.value=''}
watch(()=>form.auth,()=>{keyReader.cancel();form.keyContent='';preview.value=undefined})
onUnmounted(()=>{dialogVersion++;controller?.cancel();keyReader.cancel();form.keyContent=''})
watch(() => props.modelValue, async value => { const current=++dialogVersion;controller?.cancel();busy.value=false;checking.value=false;operation.value='';error.value='';pendingAction.value=undefined;checkToken.value='';submissionKey=requestKey();for(const key of Object.keys(fieldErrors))delete fieldErrors[key];upgrade.value=undefined;keyReader.cancel();form.keyContent='';connection.value=undefined;customDraft=false;if (!value) return; error.value = ''; preview.value = undefined; try { const loaded=await api<Settings>('/api/settings'); if(current!==dialogVersion||!props.modelValue)return;settings.value=loaded;const nodes = (settings.value.values.nodes || []) as Record<string, unknown>[]; const n = nodes.find(n => n.id === props.nodeId); const effective = settings.value.effective_nodes.find(n => n.id === props.nodeId); const ssh = {...(((settings.value.values.node_defaults||{}) as Record<string,unknown>).ssh as Record<string,unknown>||{}),...((effective?.ssh || {}) as Record<string,unknown>),...((n?.ssh || {}) as Record<string, unknown>)}, monitor = {...((effective?.monitor || {}) as Record<string,unknown>),...((n?.monitor || {}) as Record<string,unknown>)};customDraft=!!n?.monitor; Object.assign(form, { id: n?.id || '', name: n?.name || '', host: n?.host || '', enabled: n?.enabled ?? true, mode: ((effective?.deployment || n?.deployment || {}) as Record<string, unknown>).mode || 'native', port: ssh.port || 22, auth: ssh.auth_method || 'key', key: ssh.private_key_path || '', keySource:'path',keyContent:'',keyConfigured:!!(ssh.private_key_path_configured||ssh.private_key_path),password: '', override: !!n?.monitor, roots: ((monitor.roots || []) as string[]).join('\n'), extensions: ((monitor.extensions || []) as string[]).join('\n'), excludes: ((monitor.exclude_paths || []) as string[]).join('\n') });loadedDraftVersion=draftVersion } catch (e) { if(current===dialogVersion&&props.modelValue)error.value = errorMessage(e) } })
function lines(v: string) { return v.split('\n').map(v => v.trim()).filter(Boolean) }
function edit() { const node: Record<string, unknown> = { id: form.id.trim(), name: form.name.trim(), host: form.host.trim(), enabled: form.enabled, deployment: { mode: form.mode }, ssh: { username: 'root', port: Number(form.port), auth_method: form.auth, private_key_path: form.auth==='key'&&form.keySource==='path'?form.key.trim():'', password: form.password } }; if (form.override) node.monitor = { roots: lines(form.roots), extensions: lines(form.extensions), exclude_paths: lines(form.excludes) }; else node.monitor = null; return { revision: settings.value?.revision || '', patch: {}, node_id: props.nodeId, node, ssh_private_key_content:form.auth==='key'&&form.keySource==='content'?form.keyContent:undefined } }
function validateContent(){
 for(const key of Object.keys(fieldErrors))delete fieldErrors[key]
 if(!form.name.trim())fieldErrors.name='请填写服务器名称'
 if(!form.id.trim())fieldErrors.id='请填写唯一节点 ID'
 if(!form.host.trim())fieldErrors.host='请填写服务器 IP'
 if(!Number.isInteger(Number(form.port))||Number(form.port)<1||Number(form.port)>65535)fieldErrors.port='SSH 端口应为 1～65535 的整数'
 if(Object.keys(fieldErrors).length)throw new Error('请检查标红的必填字段')
 if(reading.value)throw new Error('私钥文件正在读取，请稍候')
 if(form.auth==='key'&&form.keySource==='content'&&new TextEncoder().encode(form.keyContent).length>maxPrivateKeyBytes)throw new Error('私钥内容不能超过 64 KiB')
}
async function inspect() { if(busy.value||checking.value)return;busy.value=true;error.value='';operation.value='正在校验配置并生成预览…';const current=dialogVersion,draft=draftVersion;try{validateContent();preview.value=undefined;const result=await api<Preview>('/api/settings/preview','POST',edit());if(current===dialogVersion&&draft===draftVersion&&props.modelValue){preview.value=result;operation.value='配置校验通过。请选择仅保存或保存并部署。'}}catch(e){await showError(e,current)}finally{if(current===dialogVersion)busy.value=false} }
async function save(deploy:boolean){
 if(busy.value||checking.value)return;busy.value=true;error.value='';pendingAction.value=undefined;operation.value=deploy?'正在准备部署前检查…':'正在保存配置…';const current=dialogVersion
 try{validateContent();if(deploy){const result=await automaticCheck();if(!result)return;if(result.report.items.some(i=>i.status==='warning')){pendingAction.value='deploy';operation.value='检查存在警告，请查看详情并确认后继续。';return}await submitDeployment(false)}else{await api('/api/settings','PUT',edit());if(current!==dialogVersion||!props.modelValue)return;emit('update:modelValue',false);emit('saved','配置已保存，尚未部署。');ElMessage.success('配置已保存，尚未部署')}}catch(e){await showError(e,current)}finally{if(current===dialogVersion)busy.value=false}
}
function copyRoots() { const defaults = ((settings.value?.values.node_defaults || {}) as Record<string, unknown>).monitor as Record<string, unknown> | undefined; form.roots = ((defaults?.roots || []) as string[]).join('\n'); form.extensions = ((defaults?.extensions || []) as string[]).join('\n'); form.excludes = ((defaults?.exclude_paths || []) as string[]).join('\n') }
</script>
<template><el-dialog class="node-editor-dialog" :model-value="modelValue" :title="nodeId ? '编辑子服务器' : '添加子服务器'" width="min(720px, 96vw)" @update:model-value="emit('update:modelValue', $event)"><DeploymentRequirements compact :node-id="nodeId" :mode="form.mode"/><PendingDeployment :recovery="settings?.recovery"/><el-form label-position="top" :disabled="busy || checking" @input="preview = undefined"><p v-if="nodeId" class="muted">当前版本：{{deployed?.version||'未知'}} · 运行方式：{{deployed?.mode==='docker'?'Docker':deployed?.mode==='native'?'直接运行 Go':'未知'}}</p><h3>基本信息</h3><div class="form-grid"><el-form-item label="名称" :error="fieldErrors.name"><el-input v-model="form.name" /></el-form-item><el-form-item label="唯一节点 ID" :error="fieldErrors.id"><el-input v-model="form.id" :disabled="!!nodeId" placeholder="node-example" /></el-form-item><el-form-item label="服务器 IP" :error="fieldErrors.host"><el-input v-model="form.host" :disabled="!!nodeId" /></el-form-item><el-form-item label="SSH 端口（root 用户）" :error="fieldErrors.port"><el-input v-model="form.port" type="number" /></el-form-item></div><h3>部署方式</h3><el-form-item label="部署方式"><el-select v-model="form.mode" @change="preview = undefined"><el-option label="直接运行 Go（无需 Docker）" value="native" /><el-option label="Docker 单容器" value="docker" /></el-select><small class="muted">切换前备份配置与数据库，保留网站文件、扫描任务和待投递事件。Docker 模式缺少引擎时会在支持的系统自动安装。</small></el-form-item><el-form-item label="启用节点"><el-switch v-model="form.enabled" /><small class="muted">停用只保存配置；到系统设置应用后停止中心采集与告警，节点数据保留。</small></el-form-item><h3>连接认证</h3><el-form-item label="认证方式"><el-select v-model="form.auth"><el-option label="主服务器私钥" value="key" /><el-option label="SSH 密码" value="password" /></el-select></el-form-item><template v-if="form.auth === 'key'"><el-form-item label="私钥来源"><el-radio-group v-model="form.keySource" @change="keySourceChanged"><el-radio value="path">主服务器路径</el-radio><el-radio value="content">私钥内容</el-radio></el-radio-group></el-form-item><p v-if="form.keyConfigured" class="muted">私钥已配置，留空保留；已有私钥内容不会回显。</p><el-form-item v-if="form.keySource==='path'" label="主服务器私钥绝对路径"><el-input v-model="form.key" placeholder="/root/.ssh/node-example" /></el-form-item><el-form-item v-else label="私钥内容"><div class="private-key-entry" @dragover.prevent @drop.prevent.stop="dropped"><el-input v-model="form.keyContent" data-testid="private-key-content" type="textarea" :rows="6" @input="keyReader.cancel()" autocomplete="off" spellcheck="false" placeholder="拖入私钥文件，或在这里粘贴未加密的 OpenSSH / PEM 私钥" /><div class="private-key-actions"><input ref="fileInput" data-testid="private-key-file" type="file" hidden @change="filesSelected"/><el-button :disabled="busy" @click="fileInput?.click()">选择私钥文件</el-button><span class="muted">{{reading?'正在读取文件…':'每次一个文件，最大 64 KiB；读取后请校验并预览。'}}</span></div></div></el-form-item></template><el-form-item v-else label="SSH 密码（已有密码留空保留）"><el-input v-model="form.password" type="password" autocomplete="new-password" /></el-form-item><h3>文件监控</h3><el-form-item label="监控配置来源"><el-radio-group v-model="form.override" @change="overrideChanged"><el-radio :value="false">使用公共配置（推荐）</el-radio><el-radio :value="true">为此服务器单独配置</el-radio></el-radio-group></el-form-item><div v-if="!form.override" class="inherited-monitor"><p class="muted">跟随公共配置，应用修改后生效。</p><p>监控目录：{{(publicMonitor.roots as string[]||[]).join('、')||'未配置'}}</p><p>文件后缀：{{(publicMonitor.extensions as string[]||[]).join('、')||'全部文件'}}</p><p>忽略规则：{{(publicMonitor.exclude_paths as string[]||[]).join('、')||'无'}}</p></div><div v-if="form.override"><p class="muted">下列列表整体替换公共值，后续独立维护；未展示的高级规则继续按原配置继承。</p><el-button @click="copyRoots">复制公共配置</el-button><el-form-item label="根目录，每行一个"><el-input v-model="form.roots" type="textarea" :rows="3" /></el-form-item><el-form-item label="后缀，每行一个"><el-input v-model="form.extensions" type="textarea" :rows="3" /></el-form-item><el-form-item label="忽略规则，每行一个"><el-input v-model="form.excludes" type="textarea" :rows="3" /></el-form-item></div><p class="muted">SSH 指纹自动记录。部署只处理所选节点；网站历史和其他节点继续保留。</p></el-form><div ref="details" tabindex="-1"></div><el-alert v-if="preview" :title="`校验通过：${preview.restart ? '需要部署对应服务' : '无需重建'}；范围 ${scopeLabel(preview.scope)}`" type="success" :closable="false" /><p v-if="preview" class="muted">{{(preview.changes||[]).filter(change=>change.field.endsWith('.ssh.private_key')).map(change=>`私钥：${change.after}`).join('；')}}</p><el-card v-if="connection" shadow="never"><strong>{{checking?'正在检查连接与环境':connection.ok?'连接与环境检查完成':'存在未通过的检查'}}</strong><p v-for="(item,index) in connection.items" :key="index"><el-tag :type="item.status==='passed'?'success':item.status==='failed'?'danger':item.status==='warning'?'warning':'info'">{{checkStatusLabel(item.status)}}</el-tag> {{item.name}}：{{item.message}}<span v-if="item.suggestion" class="check-advice">建议：{{item.suggestion}}</span></p></el-card><el-card v-if="upgrade" shadow="never"><h3>升级子服务器预览</h3><p>{{upgrade.scope}}</p><el-alert title="本次使用已保存配置，不保存弹窗草稿。切换部署方式请使用保存并部署。" type="warning" :closable="false"/><p v-if="upgradeDraft" class="muted">弹窗中有未保存修改，本次升级不包含这些修改。</p><p>当前版本：{{upgrade.current_version||'未知'}} → 目标版本：{{upgrade.target_version}} · {{upgrade.mode==='docker'?'Docker':'直接运行 Go'}}</p><p class="upgrade-digest">目标摘要：{{upgrade.target_image}}</p><p v-if="!upgrade.baseline_known" class="muted">缺少旧应用基线，无法确认配置差异。</p><p v-for="change in upgrade.changes" :key="change.field" class="upgrade-digest">{{change.field}}：{{change.before}} → {{change.after}}</p><el-alert v-if="upgrade.no_change" title="已是相同版本和摘要，且配置已应用，无需升级" type="success" :closable="false"/></el-card><template #footer><div v-if="statusText" class="node-operation-status" :role="error?'alert':'status'" aria-live="polite"><el-alert :title="statusText" :type="statusType" :closable="false" show-icon/><el-button v-if="preview||connection||upgrade" link type="primary" @click="showDetails">查看详情</el-button></div><el-button v-if="pendingAction" type="warning" :loading="busy" @click="confirmWarnings">确认警告并继续部署</el-button><el-button @click="emit('update:modelValue', false)">取消</el-button><el-button v-if="canUpgrade" :loading="busy" :disabled="checking||settings?.pending_task" @click="previewUpgrade">升级子服务器</el-button><el-button v-if="upgrade?.preview_token" type="warning" :loading="busy" :disabled="checking||settings?.pending_task" @click="runUpgrade">确认升级（不保存草稿）</el-button><el-button :loading="checking" :disabled="busy||reading||settings?.pending_task" @click="checkConnection">连接与环境检查</el-button><el-button :loading="busy" :disabled="reading||checking||settings?.pending_task" @click="inspect">校验并预览</el-button><el-button v-if="preview" :loading="busy" :disabled="reading||checking||settings?.pending_task" @click="save(false)">仅保存</el-button><el-button v-if="preview && form.enabled" type="primary" :loading="busy" :disabled="reading||checking||settings?.pending_task" @click="save(true)">保存并部署</el-button></template></el-dialog></template>

<style>
.node-editor-dialog.el-dialog{display:flex;flex-direction:column;max-height:calc(100dvh - 32px);margin:16px auto!important;overflow:hidden}
.node-editor-dialog>.el-dialog__header,.node-editor-dialog>.el-dialog__footer{flex-shrink:0}
.node-editor-dialog>.el-dialog__body{overflow-y:auto;min-height:0;overflow-wrap:anywhere}
.node-editor-dialog>.el-dialog__footer{display:flex;flex-wrap:wrap;justify-content:flex-end;gap:8px;border-top:1px solid var(--el-border-color-lighter);padding-top:12px}
.node-editor-dialog>.el-dialog__footer .el-button+.el-button{margin-left:0}
.node-operation-status{flex:0 0 100%;text-align:left;overflow-wrap:anywhere;max-height:25dvh;overflow-y:auto}.node-operation-status .el-alert__title{white-space:normal}.check-advice{display:block;color:var(--el-text-color-secondary);margin:4px 0}.node-editor-dialog .upgrade-digest{overflow-wrap:anywhere}
@media(max-width:600px){.node-editor-dialog .form-grid{grid-template-columns:1fr}.node-editor-dialog>.el-dialog__footer .el-button{flex:1 1 auto}}
</style>
<style scoped>.private-key-entry{width:100%;padding:12px;border:1px dashed var(--el-border-color);border-radius:8px}.private-key-actions{display:flex;align-items:center;flex-wrap:wrap;gap:12px;margin-top:10px}</style>
